import { test, expect } from '@playwright/test';

test.describe('Cookie Consent Banner - Acceptance', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/home');
  });

  test('should hide cookie consent banner after user accepts', async ({ page }) => {
    // Verify cookie consent banner is visible
    const banner = page.getByRole('banner', { name: /cookie consent/i });
    await expect(banner).toBeVisible();

    // Verify accept button is visible and clickable
    const acceptButton = page.getByRole('button', { name: /accept/i });
    await expect(acceptButton).toBeVisible();

    // Click accept button
    await acceptButton.click();

    // Verify banner disappears
    await expect(banner).not.toBeVisible();

    // Verify acceptance cookie is set
    const acceptanceCookie = page.context().cookies().find(
      (cookie: any) => cookie.name === 'cookie_consent_accepted'
    );
    expect(acceptanceCookie).toBeDefined();

    // Verify user can interact with main page content
    const mainContent = page.getByRole('main');
    await expect(mainContent).toBeVisible();
  });

  test('should not hide cookie consent banner if user closes it without accepting', async ({ page }) => {
    // Verify cookie consent banner is visible
    const banner = page.getByRole('banner', { name: /cookie consent/i });
    await expect(banner).toBeVisible();

    // Verify close button is visible and clickable
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Click close button
    await closeButton.click();

    // Verify banner remains visible
    await expect(banner).toBeVisible();

    // Verify acceptance cookie is NOT set
    const acceptanceCookie = page.context().cookies().find(
      (cookie: any) => cookie.name === 'cookie_consent_accepted'
    );
    expect(acceptanceCookie).toBeUndefined();

    // Verify user can still interact with main page content
    const mainContent = page.getByRole('main');
    await expect(mainContent).toBeVisible();
  });
});
